                  onChange={handleCycleSelectChange}
                  className="py-1 px-1 rounded text-[8px] font-mono bg-[#050000] border border-transparent hover:border-white/10 text-gray-400 cursor-pointer text-center outline-none"
                  style={{ width: '45px' }}
