                  <option value="" disabled className="bg-[#050000] text-gray-500">
                    VAR
                  </option>
                  {CUSTOM_CYCLE_VALUES.map((customVal) => (
                    <option key={customVal} value={customVal} className="bg-[#050000] text-gray-200">
                      {customVal}
                    </option>
                  ))}
                </select>
              </div>
            </div>
